import React, { useState } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  BarElement,
  ArcElement
} from 'chart.js';
import { Line, Bar, Doughnut } from 'react-chartjs-2';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
);

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [showWeatherDetails, setShowWeatherDetails] = useState(false);

  // Mock weather data
  const weatherData = {
    current: {
      temperature: 28.5,
      feelsLike: 30.2,
      humidity: 65,
      rainfall: 12.5,
      windSpeed: 18.4,
      windDirection: 'NE',
      pressure: 1012,
      uvIndex: 7,
      visibility: 10,
      condition: 'Partly Cloudy',
      icon: '⛅'
    },
    forecast: [
      { day: 'Today', temp: 28.5, minTemp: 22.3, maxTemp: 31.2, humidity: 65, rainfall: 12.5, condition: 'Partly Cloudy' },
      { day: 'Tomorrow', temp: 27.8, minTemp: 21.5, maxTemp: 30.8, humidity: 70, rainfall: 8.3, condition: 'Light Rain' },
      { day: 'Wed', temp: 29.1, minTemp: 23.0, maxTemp: 32.5, humidity: 58, rainfall: 2.1, condition: 'Sunny' },
      { day: 'Thu', temp: 26.4, minTemp: 20.8, maxTemp: 29.7, humidity: 72, rainfall: 15.2, condition: 'Heavy Rain' },
      { day: 'Fri', temp: 27.2, minTemp: 21.9, maxTemp: 30.4, humidity: 68, rainfall: 5.7, condition: 'Partly Cloudy' },
      { day: 'Sat', temp: 28.9, minTemp: 23.1, maxTemp: 33.0, humidity: 55, rainfall: 0.0, condition: 'Sunny' },
      { day: 'Sun', temp: 27.5, minTemp: 22.0, maxTemp: 31.8, humidity: 62, rainfall: 3.4, condition: 'Cloudy' },
    ],
    alerts: [
      { type: 'warning', message: 'Heavy rainfall expected on Thursday. Prepare drainage systems.' },
      { type: 'info', message: 'High UV index today. Apply sun protection for crops.' },
      { type: 'success', message: 'Optimal planting conditions this weekend.' }
    ],
    historical: {
      labels: ['Week 1', 'Week 2', 'Week 3', 'Week 4', 'Week 5', 'Week 6', 'Week 7', 'Week 8'],
      rainfall: [8.2, 12.5, 5.3, 15.8, 3.1, 10.2, 7.8, 14.5],
      temperature: [26.5, 27.8, 28.2, 26.9, 29.1, 28.5, 27.3, 26.8]
    }
  };

  // Mock system status
  const systemStatus = {
    datasetLoaded: true,
    trainingStatus: {
      sarima: 'Trained',
      lstm: 'Trained',
      hybrid: 'Trained'
    }
  };

  // Mock data preview
  const mockPreviewData = [
    { Date: '2024-01-01', Rainfall: 12.5, Max_Temp: 28.3, Min_Temp: 22.1, Humidity: 65, Crop_Yield: 4.2 },
    { Date: '2024-01-02', Rainfall: 8.2, Max_Temp: 29.1, Min_Temp: 23.4, Humidity: 58, Crop_Yield: 4.5 },
    { Date: '2024-01-03', Rainfall: 0.0, Max_Temp: 31.2, Min_Temp: 24.8, Humidity: 45, Crop_Yield: 4.8 },
    { Date: '2024-01-04', Rainfall: 15.8, Max_Temp: 27.5, Min_Temp: 21.9, Humidity: 72, Crop_Yield: 3.9 },
    { Date: '2024-01-05', Rainfall: 5.3, Max_Temp: 30.4, Min_Temp: 23.7, Humidity: 55, Crop_Yield: 4.6 },
  ];

  // Mock predictions
  const mockPredictions = [4.2, 4.5, 4.8, 4.3, 4.6, 4.9, 4.7, 5.0, 4.8, 4.4, 4.7, 5.1, 4.9, 5.2, 4.8];
  
  // Mock recommendations
  const mockRecommendations = [
    {
      category: 'Rainfall',
      level: 'Normal',
      suggestion: 'Normal rainfall expected. Continue with regular planting schedule.'
    },
    {
      category: 'Temperature',
      level: 'Medium',
      suggestion: 'Moderate temperatures expected. Maintain regular irrigation schedule.'
    },
    {
      category: 'Humidity',
      level: 'Medium',
      suggestion: 'Humidity levels are moderate. Monitor for potential fungal growth.'
    },
    {
      category: 'Yield Stability',
      level: 'Stable',
      suggestion: 'Stable yield expected. Maintain current farming practices.'
    },
    {
      category: 'General',
      level: 'Info',
      suggestion: 'Monitor weather conditions daily and adjust irrigation accordingly.'
    }
  ];

  // Mock instability analysis
  const instabilityAnalysis = {
    level: 'Low',
    mean: 4.7,
    std: 0.28,
    cv: 0.06
  };

  // ============= WEATHER MONITOR COMPONENT =============
  const WeatherMonitor = () => {
    const [selectedDay, setSelectedDay] = useState(0);

    // Weather alert icons
    const getAlertIcon = (type) => {
      switch(type) {
        case 'warning': return '⚠️';
        case 'info': return 'ℹ️';
        case 'success': return '✅';
        default: return '📢';
      }
    };

    const getAlertColor = (type) => {
      switch(type) {
        case 'warning': return '#f39c12';
        case 'info': return '#3498db';
        case 'success': return '#27ae60';
        default: return '#7f8c8d';
      }
    };

    // Weather condition icon
    const getWeatherIcon = (condition) => {
      const icons = {
        'Sunny': '☀️',
        'Partly Cloudy': '⛅',
        'Cloudy': '☁️',
        'Light Rain': '🌦️',
        'Heavy Rain': '🌧️',
        'Thunderstorm': '⛈️'
      };
      return icons[condition] || '🌤️';
    };

    return (
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h2>🌤️ Weather Monitor</h2>
          <div style={{ display: 'flex', gap: '10px' }}>
            <button 
              className="btn-secondary"
              onClick={() => setShowWeatherDetails(!showWeatherDetails)}
            >
              {showWeatherDetails ? '📊 Hide Details' : '📊 Show Details'}
            </button>
            <button className="btn-secondary">🔄 Refresh</button>
          </div>
        </div>

        {/* Current Weather Card */}
        <div className="weather-current" style={{
          background: 'linear-gradient(135deg, #2c3e50 0%, #3498db 100%)',
          borderRadius: '20px',
          padding: '30px',
          color: 'white',
          marginBottom: '20px'
        }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr 1fr', gap: '20px' }}>
            <div>
              <h3 style={{ fontSize: '3rem', margin: '0' }}>
                {weatherData.current.temperature}°C
              </h3>
              <p style={{ fontSize: '1.2rem', margin: '5px 0' }}>
                Feels like {weatherData.current.feelsLike}°C
              </p>
              <p style={{ fontSize: '1.5rem' }}>
                {weatherData.current.icon} {weatherData.current.condition}
              </p>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
              <div>
                <p style={{ opacity: 0.7, margin: '0' }}>💧 Humidity</p>
                <p style={{ fontSize: '1.2rem', fontWeight: 'bold', margin: '0' }}>
                  {weatherData.current.humidity}%
                </p>
              </div>
              <div>
                <p style={{ opacity: 0.7, margin: '0' }}>🌧️ Rainfall</p>
                <p style={{ fontSize: '1.2rem', fontWeight: 'bold', margin: '0' }}>
                  {weatherData.current.rainfall} mm
                </p>
              </div>
              <div>
                <p style={{ opacity: 0.7, margin: '0' }}>💨 Wind</p>
                <p style={{ fontSize: '1.2rem', fontWeight: 'bold', margin: '0' }}>
                  {weatherData.current.windSpeed} km/h
                </p>
              </div>
              <div>
                <p style={{ opacity: 0.7, margin: '0' }}>☀️ UV Index</p>
                <p style={{ fontSize: '1.2rem', fontWeight: 'bold', margin: '0' }}>
                  {weatherData.current.uvIndex}
                </p>
              </div>
            </div>
            <div style={{ textAlign: 'right' }}>
              <p style={{ margin: '0' }}>📅 {new Date().toLocaleDateString('en-US', { 
                weekday: 'long', 
                year: 'numeric', 
                month: 'long', 
                day: 'numeric' 
              })}</p>
              <p style={{ margin: '5px 0', opacity: 0.7 }}>
                Pressure: {weatherData.current.pressure} hPa
              </p>
              <p style={{ margin: '5px 0', opacity: 0.7 }}>
                Visibility: {weatherData.current.visibility} km
              </p>
            </div>
          </div>
        </div>

        {/* Weather Alerts */}
        {weatherData.alerts && weatherData.alerts.length > 0 && (
          <div style={{ marginBottom: '20px' }}>
            <h4>🔔 Weather Alerts</h4>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: '10px' }}>
              {weatherData.alerts.map((alert, idx) => (
                <div key={idx} style={{
                  padding: '12px 20px',
                  borderRadius: '10px',
                  background: `${getAlertColor(alert.type)}20`,
                  borderLeft: `4px solid ${getAlertColor(alert.type)}`,
                  display: 'flex',
                  alignItems: 'center',
                  gap: '10px'
                }}>
                  <span style={{ fontSize: '1.5rem' }}>{getAlertIcon(alert.type)}</span>
                  <span>{alert.message}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 7-Day Forecast */}
        <div style={{ marginBottom: '20px' }}>
          <h4>📊 7-Day Forecast</h4>
          <div style={{ 
            display: 'grid', 
            gridTemplateColumns: 'repeat(7, 1fr)', 
            gap: '10px',
            overflowX: 'auto',
            padding: '5px 0'
          }}>
            {weatherData.forecast.map((day, idx) => (
              <div key={idx} 
                className={`weather-day ${idx === selectedDay ? 'selected' : ''}`}
                style={{
                  background: idx === selectedDay ? '#3498db' : 'white',
                  color: idx === selectedDay ? 'white' : '#2c3e50',
                  padding: '15px 10px',
                  borderRadius: '12px',
                  textAlign: 'center',
                  cursor: 'pointer',
                  boxShadow: '0 2px 5px rgba(0,0,0,0.1)',
                  transition: 'all 0.3s ease',
                  minWidth: '100px',
                  border: idx === selectedDay ? 'none' : '1px solid #e0e0e0'
                }}
                onClick={() => setSelectedDay(idx)}
                onMouseEnter={(e) => {
                  if (idx !== selectedDay) {
                    e.currentTarget.style.transform = 'translateY(-5px)';
                  }
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = 'translateY(0)';
                }}
              >
                <div style={{ fontSize: '1.5rem' }}>{getWeatherIcon(day.condition)}</div>
                <div style={{ fontWeight: '600', marginTop: '5px' }}>{day.day}</div>
                <div style={{ fontSize: '1.2rem', fontWeight: 'bold' }}>{day.temp}°</div>
                <div style={{ fontSize: '0.8rem', opacity: 0.7 }}>
                  {day.minTemp}° / {day.maxTemp}°
                </div>
                <div style={{ fontSize: '0.8rem', opacity: 0.7 }}>
                  💧 {day.humidity}% | 🌧️ {day.rainfall}mm
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Weather Charts */}
        {showWeatherDetails && (
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
            <div className="card">
              <h4>📈 Historical Rainfall Pattern</h4>
              <div className="chart-container">
                <Bar 
                  data={{
                    labels: weatherData.historical.labels,
                    datasets: [{
                      label: 'Rainfall (mm)',
                      data: weatherData.historical.rainfall,
                      backgroundColor: 'rgba(52, 152, 219, 0.6)',
                      borderColor: '#3498db',
                      borderWidth: 1
                    }]
                  }}
                  options={{
                    responsive: true,
                    plugins: {
                      legend: { position: 'top' }
                    },
                    scales: {
                      y: { beginAtZero: true }
                    }
                  }}
                />
              </div>
            </div>

            <div className="card">
              <h4>📈 Temperature Trend</h4>
              <div className="chart-container">
                <Line 
                  data={{
                    labels: weatherData.historical.labels,
                    datasets: [{
                      label: 'Temperature (°C)',
                      data: weatherData.historical.temperature,
                      borderColor: '#e74c3c',
                      backgroundColor: 'rgba(231, 76, 60, 0.1)',
                      fill: true,
                      tension: 0.4
                    }]
                  }}
                  options={{
                    responsive: true,
                    plugins: {
                      legend: { position: 'top' }
                    },
                    scales: {
                      y: { beginAtZero: false }
                    }
                  }}
                />
              </div>
            </div>

            <div className="card" style={{ gridColumn: '1 / -1' }}>
              <h4>🌡️ Weather Conditions Summary</h4>
              <div style={{ 
                display: 'grid', 
                gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', 
                gap: '15px',
                marginTop: '10px'
              }}>
                <div style={{ textAlign: 'center', padding: '15px', background: '#f8f9fa', borderRadius: '10px' }}>
                  <div style={{ fontSize: '2rem' }}>☀️</div>
                  <div>Clear Days</div>
                  <div style={{ fontWeight: 'bold' }}>12</div>
                </div>
                <div style={{ textAlign: 'center', padding: '15px', background: '#f8f9fa', borderRadius: '10px' }}>
                  <div style={{ fontSize: '2rem' }}>🌧️</div>
                  <div>Rainy Days</div>
                  <div style={{ fontWeight: 'bold' }}>8</div>
                </div>
                <div style={{ textAlign: 'center', padding: '15px', background: '#f8f9fa', borderRadius: '10px' }}>
                  <div style={{ fontSize: '2rem' }}>💨</div>
                  <div>Windy Days</div>
                  <div style={{ fontWeight: 'bold' }}>5</div>
                </div>
                <div style={{ textAlign: 'center', padding: '15px', background: '#f8f9fa', borderRadius: '10px' }}>
                  <div style={{ fontSize: '2rem' }}>🌡️</div>
                  <div>Avg Temperature</div>
                  <div style={{ fontWeight: 'bold' }}>28.5°C</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Farming Impact */}
        <div className="card" style={{ marginTop: '20px' }}>
          <h4>🌾 Weather Impact on Farming</h4>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '15px' }}>
            <div style={{ padding: '15px', background: '#e8f8f0', borderRadius: '10px', borderLeft: '4px solid #27ae60' }}>
              <h5 style={{ margin: '0', color: '#27ae60' }}>✅ Good Conditions</h5>
              <p style={{ margin: '5px 0', fontSize: '0.9rem' }}>
                • Moderate temperatures (20-30°C)<br />
                • Adequate soil moisture<br />
                • Optimal growing conditions
              </p>
            </div>
            <div style={{ padding: '15px', background: '#fef9e7', borderRadius: '10px', borderLeft: '4px solid #f39c12' }}>
              <h5 style={{ margin: '0', color: '#f39c12' }}>⚠️ Watch Out</h5>
              <p style={{ margin: '5px 0', fontSize: '0.9rem' }}>
                • Heavy rain expected Thursday<br />
                • High humidity may cause disease<br />
                • Monitor pest activity
              </p>
            </div>
            <div style={{ padding: '15px', background: '#fdebd0', borderRadius: '10px', borderLeft: '4px solid #e74c3c' }}>
              <h5 style={{ margin: '0', color: '#e74c3c' }}>⚡ Actions Needed</h5>
              <p style={{ margin: '5px 0', fontSize: '0.9rem' }}>
                • Prepare drainage systems<br />
                • Apply preventive fungicides<br />
                • Adjust irrigation schedule
              </p>
            </div>
          </div>
        </div>
      </div>
    );
  };

  // ============= RENDER HELPERS =============
  const renderStatusIndicator = (status) => {
    return (
      <span className={status === 'Trained' ? 'value loaded' : 'value not-loaded'}>
        {status === 'Trained' ? '✅' : '❌'} {status}
      </span>
    );
  };

  const getLevelClass = (level) => {
    const levelMap = {
      'High': 'level-high',
      'Medium': 'level-medium',
      'Low': 'level-low',
      'Unstable': 'level-high',
      'Stable': 'level-low',
      'Info': 'level-low'
    };
    return levelMap[level] || 'level-medium';
  };

  // ============= RENDER TABS =============
  const renderDashboard = () => (
    <div className="dashboard-grid">
      <div className="card">
        <h3>📊 System Status</h3>
        <div className="status-item">
          <span className="label">Dataset:</span>
          <span className="value loaded">✅ Loaded</span>
        </div>
        <div className="status-item">
          <span className="label">SARIMA Model:</span>
          {renderStatusIndicator('Trained')}
        </div>
        <div className="status-item">
          <span className="label">LSTM Model:</span>
          {renderStatusIndicator('Trained')}
        </div>
        <div className="status-item">
          <span className="label">Hybrid Model:</span>
          {renderStatusIndicator('Trained')}
        </div>
      </div>

      <div className="card">
        <h3>⚡ Quick Actions</h3>
        <div className="quick-actions">
          <button onClick={() => setActiveTab('weather')}>🌤️ Weather Monitor</button>
          <button onClick={() => setActiveTab('data')}>📊 Import Data</button>
          <button onClick={() => setActiveTab('training')}>🤖 Train Models</button>
          <button onClick={() => setActiveTab('predictions')}>📈 View Predictions</button>
          <button onClick={() => setActiveTab('recommendations')}>💡 Recommendations</button>
        </div>
      </div>

      <div className="card full-width">
        <h3>📋 Data Preview</h3>
        <div>
          <p style={{ marginBottom: '10px', color: '#7f8c8d' }}>
            {mockPreviewData.length} rows × 6 columns
          </p>
          <div className="table-container">
            <table>
              <thead>
                <tr>
                  {Object.keys(mockPreviewData[0]).map(col => (
                    <th key={col}>{col}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {mockPreviewData.slice(0, 5).map((row, idx) => (
                  <tr key={idx}>
                    {Object.values(row).map((val, i) => (
                      <td key={i}>{val}</td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );

  const renderDataManagement = () => (
    <div>
      <h2>📁 Data Management</h2>
      <p style={{ color: '#7f8c8d', marginBottom: '20px' }}>
        Upload your weather and crop yield dataset in CSV or Excel format.
      </p>

      <div className="dropzone">
        <div>
          <p style={{ fontSize: '3rem', marginBottom: '10px' }}>📤</p>
          <p style={{ fontSize: '1.2rem', fontWeight: '600' }}>
            Drag & drop your dataset here
          </p>
          <p style={{ color: '#7f8c8d' }}>
            or click to browse (CSV, XLSX, XLS)
          </p>
          <p style={{ color: '#95a5a6', fontSize: '0.8rem', marginTop: '10px' }}>
            Max file size: 16MB
          </p>
        </div>
      </div>

      <div style={{ marginTop: '20px' }}>
        <h3>📋 Validation Report</h3>
        <div className="card">
          <div style={{ marginBottom: '10px' }}>
            <h4 style={{ color: '#e67e22' }}>⚠️ Warnings</h4>
            <ul>
              <li>Dataset has 3 of the recommended columns. Expected: Rainfall, Max_Temp, Min_Temp, Humidity, Crop_Yield</li>
            </ul>
          </div>
          <div style={{ color: '#27ae60', fontWeight: '600' }}>
            ✅ Dataset passed validation
          </div>
        </div>
      </div>

      <div style={{ marginTop: '20px' }}>
        <h3>📊 Dataset Preview</h3>
        <div className="table-container">
          <table>
            <thead>
              <tr>
                {Object.keys(mockPreviewData[0]).map(col => (
                  <th key={col}>{col}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {mockPreviewData.map((row, idx) => (
                <tr key={idx}>
                  {Object.values(row).map((val, i) => (
                    <td key={i}>{val}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
          <p style={{ marginTop: '10px', color: '#7f8c8d' }}>
            Showing {mockPreviewData.length} rows
          </p>
        </div>
      </div>
    </div>
  );

  const renderTraining = () => (
    <div>
      <h2>🤖 Model Training</h2>
      <p style={{ color: '#7f8c8d', marginBottom: '20px' }}>
        Train SARIMA, LSTM, and Hybrid models for weather and crop yield prediction.
      </p>

      <div className="training-controls">
        <div className="control-group">
          <label>Target Variable</label>
          <select>
            <option value="Crop_Yield">Crop Yield</option>
            <option value="Rainfall">Rainfall</option>
            <option value="Max_Temp">Max Temperature</option>
            <option value="Min_Temp">Min Temperature</option>
            <option value="Humidity">Humidity</option>
          </select>
        </div>

        <div className="control-group">
          <label>Sequence Length (LSTM)</label>
          <input type="number" value="30" min="10" max="60" />
        </div>

        <div className="control-group">
          <label>Epochs (LSTM)</label>
          <input type="number" value="100" min="50" max="500" />
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
        <div className="card">
          <h3>📈 SARIMA Model</h3>
          <p style={{ color: '#7f8c8c', marginBottom: '15px' }}>
            Seasonal ARIMA for weather forecasting
          </p>
          <div style={{ marginBottom: '15px' }}>
            Status: <span style={{ color: '#27ae60' }}>✅ Trained</span>
          </div>
          <button className="btn-secondary">Train SARIMA</button>
        </div>

        <div className="card">
          <h3>🧠 LSTM Model</h3>
          <p style={{ color: '#7f8c8c', marginBottom: '15px' }}>
            Long Short-Term Memory for yield prediction
          </p>
          <div style={{ marginBottom: '15px' }}>
            Status: <span style={{ color: '#27ae60' }}>✅ Trained</span>
          </div>
          <button className="btn-secondary">Train LSTM</button>
        </div>

        <div className="card">
          <h3>🔀 Hybrid Model</h3>
          <p style={{ color: '#7f8c8c', marginBottom: '15px' }}>
            SARIMA-LSTM combined approach
          </p>
          <div style={{ marginBottom: '15px' }}>
            Status: <span style={{ color: '#27ae60' }}>✅ Trained</span>
          </div>
          <button className="btn-primary">Train Hybrid</button>
        </div>
      </div>
    </div>
  );

  const renderPredictions = () => (
    <div>
      <h2>📈 Predictions</h2>
      <p style={{ color: '#7f8c8d', marginBottom: '20px' }}>
        Generate predictions using trained models and view forecasted results.
      </p>

      <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap', marginBottom: '20px' }}>
        <div className="control-group">
          <label>Model Type</label>
          <select>
            <option value="sarima">SARIMA</option>
            <option value="lstm">LSTM</option>
            <option value="hybrid" selected>Hybrid (SARIMA-LSTM)</option>
          </select>
        </div>

        <div className="control-group">
          <label>Forecast Period (Days)</label>
          <input type="number" value="30" min="7" max="90" />
        </div>

        <div className="control-group" style={{ display: 'flex', alignItems: 'flex-end' }}>
          <button className="btn-primary">Generate Predictions</button>
        </div>
      </div>

      <div>
        <div className="card">
          <h3>📈 Forecast Results</h3>
          <div className="chart-container">
            <Line 
              data={{
                labels: Array.from({ length: mockPredictions.length }, (_, i) => `Day ${i + 1}`),
                datasets: [{
                  label: 'Predicted Crop Yield',
                  data: mockPredictions,
                  borderColor: '#3498db',
                  backgroundColor: 'rgba(52, 152, 219, 0.1)',
                  fill: true,
                  tension: 0.4
                }]
              }}
              options={{
                responsive: true,
                plugins: {
                  legend: { position: 'top' },
                  title: { display: true, text: 'Crop Yield Forecast' }
                },
                scales: { 
                  y: { 
                    beginAtZero: true,
                    title: { display: true, text: 'Yield (tons/ha)' }
                  }
                }
              }}
            />
          </div>
          <div style={{ marginTop: '15px' }}>
            <h4>Summary Statistics</h4>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px' }}>
              <div>
                <p><strong>Min:</strong> {Math.min(...mockPredictions).toFixed(2)}</p>
              </div>
              <div>
                <p><strong>Max:</strong> {Math.max(...mockPredictions).toFixed(2)}</p>
              </div>
              <div>
                <p><strong>Mean:</strong> {(mockPredictions.reduce((a, b) => a + b, 0) / mockPredictions.length).toFixed(2)}</p>
              </div>
            </div>
          </div>
        </div>

        <div className="card" style={{ marginTop: '20px' }}>
          <h3>📊 Yield Instability Analysis</h3>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '20px' }}>
            <div>
              <h4>Stability Level</h4>
              <span className={`level ${getLevelClass(instabilityAnalysis.level)}`}>
                {instabilityAnalysis.level}
              </span>
            </div>
            <div>
              <h4>Mean Yield</h4>
              <p style={{ fontSize: '1.2rem', fontWeight: '600' }}>
                {instabilityAnalysis.mean.toFixed(2)} tons/ha
              </p>
            </div>
            <div>
              <h4>Coefficient of Variation</h4>
              <p style={{ fontSize: '1.2rem', fontWeight: '600' }}>
                {(instabilityAnalysis.cv * 100).toFixed(1)}%
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderRecommendations = () => (
    <div>
      <h2>💡 Farming Recommendations</h2>
      <p style={{ color: '#7f8c8d', marginBottom: '20px' }}>
        Get actionable recommendations based on weather forecasts and yield predictions.
      </p>

      <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap', marginBottom: '20px' }}>
        <div className="control-group">
          <label>Model Type</label>
          <select>
            <option value="hybrid" selected>Hybrid (Recommended)</option>
            <option value="sarima">SARIMA</option>
            <option value="lstm">LSTM</option>
          </select>
        </div>

        <div className="control-group">
          <label>Forecast Period (Days)</label>
          <input type="number" value="30" min="7" max="90" />
        </div>

        <div className="control-group" style={{ display: 'flex', alignItems: 'flex-end' }}>
          <button className="btn-primary">Get Recommendations</button>
        </div>
      </div>

      <div className="card">
        <h3>📋 Recommendations</h3>
        {mockRecommendations.map((rec, idx) => (
          <div key={idx} className="recommendation-card">
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span className="category">{rec.category}</span>
              <span className={`level ${getLevelClass(rec.level)}`}>
                {rec.level}
              </span>
            </div>
            <p style={{ marginTop: '10px', fontSize: '1.05rem' }}>
              {rec.suggestion}
            </p>
          </div>
        ))}
      </div>

      <div className="card" style={{ marginTop: '20px' }}>
        <h3>📋 Seasonal Farming Guide</h3>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '10px' }}>
          {['January', 'February', 'March', 'April', 'May', 'June',
            'July', 'August', 'September', 'October', 'November', 'December'].map(month => (
            <div key={month} style={{ 
              padding: '10px', 
              background: '#f8f9fa', 
              borderRadius: '8px',
              borderLeft: '3px solid #3498db'
            }}>
              <strong>{month}</strong>
              <p style={{ fontSize: '0.85rem', marginTop: '5px', color: '#7f8c8d' }}>
                {getSeasonalTip(month)}
              </p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  const getSeasonalTip = (month) => {
    const tips = {
      'January': 'Prepare land for dry season planting, monitor water sources',
      'February': 'Plant drought-resistant varieties, apply mulch to conserve moisture',
      'March': 'Begin regular irrigation, monitor pest activity',
      'April': 'Fertilize crops, watch for fungal diseases',
      'May': 'Continue pest management, prepare for rainy season',
      'June': 'Adjust irrigation based on rainfall, monitor flood risk',
      'July': 'Apply preventive fungicides, ensure proper drainage',
      'August': 'Harvest early-maturing crops, prepare storage facilities',
      'September': 'Plant short-cycle crops, monitor post-harvest losses',
      'October': 'Begin main season planting, prepare for cool weather',
      'November': 'Apply balanced fertilizers, monitor cold stress',
      'December': 'Reduce irrigation, plan next season\'s planting'
    };
    return tips[month] || 'Regular farming activities recommended';
  };

  const renderTabContent = () => {
    switch(activeTab) {
      case 'dashboard': return renderDashboard();
      case 'weather': return <WeatherMonitor />;
      case 'data': return renderDataManagement();
      case 'training': return renderTraining();
      case 'predictions': return renderPredictions();
      case 'recommendations': return renderRecommendations();
      default: return renderDashboard();
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>🌾 ClimaYield-X</h1>
        <p className="subtitle">Smart Agricultural Forecasting & Decision Support System</p>
      </header>

      <nav className="nav-tabs">
        <button className={activeTab === 'dashboard' ? 'active' : ''} onClick={() => setActiveTab('dashboard')}>
          📊 Dashboard
        </button>
        <button className={activeTab === 'weather' ? 'active' : ''} onClick={() => setActiveTab('weather')}>
          🌤️ Weather Monitor
        </button>
        <button className={activeTab === 'data' ? 'active' : ''} onClick={() => setActiveTab('data')}>
          📁 Data Management
        </button>
        <button className={activeTab === 'training' ? 'active' : ''} onClick={() => setActiveTab('training')}>
          🤖 Model Training
        </button>
        <button className={activeTab === 'predictions' ? 'active' : ''} onClick={() => setActiveTab('predictions')}>
          📈 Predictions
        </button>
        <button className={activeTab === 'recommendations' ? 'active' : ''} onClick={() => setActiveTab('recommendations')}>
          💡 Recommendations
        </button>
      </nav>

      <main className="main-content">
        {renderTabContent()}
      </main>

      <ToastContainer position="bottom-right" />
    </div>
  );
}

export default App;
